mapper.select:
SELECT QUESTION_ID, QUESTION_TEMPLATE_ID, QUESTION_TYPE, QUESTION_TITLE, QUESTION_DESCRIPTION, REQUIRED_YN, SCORED_YN, QUESTION_SCORE, CORRECT_ANSWER, ANSWER_MATCH_MODE, SORT_ORDER FROM POPUP.POPUP_QUESTION WHERE QUESTION_TEMPLATE_ID IN
#{templateId}
ORDER BY QUESTION_TEMPLATE_ID, SORT_ORDER

SELECT OPTION_ID, QUESTION_ID, OPTION_VALUE, OPTION_TEXT, CORRECT_YN, SORT_ORDER FROM POPUP.POPUP_OPTION WHERE QUESTION_ID IN
#{questionId}
ORDER BY QUESTION_ID, SORT_ORDER

SELECT FROM_TZ(HIDDEN_UNTIL_AT, 'Asia/Seoul')
FROM POPUP.USER_POPUP_STATUS
WHERE EMPLOYEE_NO = #{userId}
  AND POPUP_ID = #{popupId}

mapper.insert:
INSERT INTO POPUP.POPUP_RESPONSE_VALUE
(
    RESPONSE_VALUE_ID, RESPONSE_ANSWER_ID, OPTION_ID, SELECTED_VALUE,
    CREATED_BY, UPDATED_BY
)
VALUES
(
    POPUP.SEQ_POPUP_RESPONSE_VALUE.NEXTVAL, #{responseAnswerId}, #{optionId}, #{selectedValue},
    #{userId}, #{userId}
)

mapper.select:
SELECT FROM_TZ(COMPLETED_AT, 'Asia/Seoul')
FROM POPUP.VIDEO_VIEW_STATUS
WHERE EMPLOYEE_NO = #{userId}
  AND POPUP_ID = #{popupId}
